	podManager = mocks.PodManager{}
	podManager.
		On("SchedulePodsRestart", mock.Anything, mock.Anything).
		Return(nil)
	podManager.
		On("ScheduleCheckOnPodCompletion", mock.Anything, mock.Anything).
		Return(nil)
